{"action":"python","code":"import urllib.request,json,os,concurrent.futures,xarray as xr
for date in ['2026-09-27','2026-09-20']:
 p=f'{date}/data/ECMWF_s2s_precip_{date}.zarr/'
 d=json.load(urllib.request.urlopen('https://storage.googleapis.com/storage/v1/b/kenya-forecasting-data/o?prefix='+p))
 def fetch(x):
  name=x['name']; out='/work/'+name; os.makedirs(os.path.dirname(out),exist_ok=True); open(out,'wb').write(urllib.request.urlopen('https://storage.googleapis.com/kenya-forecasting-data/'+name).read())
 with concurrent.futures.ThreadPoolExecutor(8) as ex: list(ex.map(fetch,d['items']))
 ds=xr.open_zarr('/work/'+p,chunks=None); print(ds); print(ds.attrs); print(ds.tp.attrs); print('step',ds.step.values); print('valid',ds.valid_time.values); print('time',ds.time.values); print('lat lon',ds.latitude.values,ds.longitude.values); print('members',ds.number.values)
"}

